{
  "kind": "foreground",
  "exitCode": 0,
  "signal": null,
  "timedOut": false,
  "aborted": false,
  "timeoutMs": 120000,
  "stdout": {
    "text": "14634\r\n--- subagent dirs ---\r\n38\r\n",
    "truncated": false
  },
  "stderr": {
    "text": "",
    "truncated": false
  },
  "sandbox": {
    "mode": "danger-full-access",
    "denied": false
  }
}

{
  "analyze": "// 用法: node _analyze_session.cjs <session.jsonl路径> <输出报告路径> [--grep 关键词]
const fs = require("fs");
const path = require("path");
const args = process.argv.slice(2);
const src = args[0];
const out = args[1] || path.join(path.dirname(src), "_report.txt");
const grepIdx = args.indexOf("--grep");
const grep = grepIdx >= 0 ? args[grepIdx + 1] : null;

const lines = fs.readFileSync(src, "utf8").split(/\r?\n/).filter(Boolean);
const outLines = [];
const p = (s) => { outLines.push(s); };

p("SRC: " + src);
p("TOTAL LINES: " + lines.length);
p("");

function brief(v, n) {
  n = n || 160;
  let s;
  try { s = JSON.stringify(v); } catch (e) { s = String(v); }
  if (s.length > n) s = s.slice(0, n) + " ...(" + s.length + " chars)";
  return s;
}
const first = JSON.parse(lines[0]);
p("LINE1 KEYS: " + Object.keys(first).join(", "));
p("LINE1: " + brief(first, 1200));
p("");
// 类型统计
const typeCount = {};
const roleCount = {};
const getText = (o) => {
  const cands = ["text", "content", "message", "prompt"];
  for (const c of cands) {
    if (typeof o[c] === "string") return o[c];
    if (o[c] && typeof o[c] === "object") {
      if (typeof o[c].text === "string") return o[c].text;
      if (typeof o[c].content === "string") return o[c].content;
    }
  }
  return "";
};

const grepHits = [];
for (let i = 0; i < lines.length; i++) {
  let o = null;
  try { o = JSON.parse(lines[i]); } catch (e) {
    p("!! PARSE FAIL line " + (i + 1) + ": " + e.message);
    continue;
  }
  const t = o.type || o.kind || o.role || "?";
  typeCount[t] = (typeCount[t] || 0) + 1;
  const r = o.message && o.message.role ? o.message.role : (o.role || "");
  if (r) roleCount[r] = (roleCount[r] || 0) + 1;
  if (grep) {
    if (lines[i].includes(grep)) grepHits.push(i + 1);
  }
}
p("TYPE COUNTS: " + JSON.stringify(typeCount));
p("ROLE COUNTS: " + JSON.stringify(roleCount));
p("");

if (grep) {
  p("GREP [" + grep + "] HITS: " + grepHits.length + " lines");
  p("LINES: " + grepHits.join(","));
  p("");
  for (const ln of grepHits.slice(0, 80)) {
    let o = null;
    try { o = JSON.parse(lines[ln - 1]); } catch (e) { o = null; }
    const head = o ? (o.type || o.kind || "?") + " | " + (o.message && o.message.role ? o.message.role : (o.role || "")) : "RAW";
    p("L" + ln + " [" + head + "] " + brief(o ? getText(o.message || o) || lines[ln - 1] : lines[ln - 1], 400));
  }
  p("");
}

fs.writeFileSync(out, outLines.join("\n"), "utf8");
console.log("REPORT WRITTEN: " + out + " (" + outLines.length + " lines)");",
  "subagents": "// 用法: node _analyze_subagents.cjs <subagentsDir> <outFile>
const fs = require("fs");
const path = require("path");
const dir = process.argv[2];
const out = process.argv[3] || path.join(dir, "_subagents_report.txt");
const outLines = [];
const p = (s) => { outLines.push(s); };
function extractText(o) {
  const d = o && o.data ? o.data : o;
  if (!d) return "";
  let c = d.content;
  if (c && typeof c === "object" && !Array.isArray(c)) c = c.content || c.text || c.message;
  if (typeof c === "string") return c;
  if (Array.isArray(c)) {
    return c.map(b => {
      if (typeof b === "string") return b;
      if (b && typeof b.text === "string") return b.text;
      return "";
    }).filter(Boolean).join(" ");
  }
  if (d.message) {
    const m = d.message;
    if (typeof m.content === "string") return m.content;
    if (Array.isArray(m.content)) return extractText({ data: m });
  }
  return "";
}
const dirs = fs.readdirSync(dir).filter(n => {
  const fp = path.join(dir, n, "session.jsonl");
  try { return fs.statSync(fp).isFile(); } catch (e) { return false; }
});
p("SUBAGENT SESSIONS: " + dirs.length);
p("");
const rows = [];
for (const d of dirs) {
  const fp = path.join(dir, d, "session.jsonl");
  const lines = fs.readFileSync(fp, "utf8").split(/\r?\n/).filter(Boolean);
  let firstUser = "", lastAsst = "", t0 = 0, t1 = 0;
  const tc = {};
  for (let i = 0; i < lines.length; i++) {
    let o = null;
    try { o = JSON.parse(lines[i]); } catch (e) { o = null; }
    if (!o) continue;
    tc[o.type] = (tc[o.type] || 0) + 1;
    if (o.time) { if (!t0) t0 = o.time; t1 = o.time; }
    if (o.type === "user/message" && !firstUser) {
      const txt = extractText(o).replace(/\s+/g, " ").trim();
      if (txt && txt.indexOf("<goal_round>") < 0) firstUser = txt;
    }
    if (o.type === "assistant/message") {
      const txt = extractText(o).replace(/\s+/g, " ").trim();
      if (txt) lastAsst = txt;
    }
  }
  rows.push({ id: d, lines: lines.length, t0, t1, firstUser, lastAsst, tc });
}
for (const r of rows) {
  p("=== " + r.id + " | " + r.lines + " lines | " + (r.t0 ? new Date(r.t0 + 28800000).toISOString().replace("T", " ").slice(0, 16) : "?") + " -> " + (r.t1 ? new Date(r.t1 + 28800000).toISOString().replace("T", " ").slice(0, 16) : "?") + " | calls: tool=" + (r.tc["tool/call"] || 0) + " retry=" + (r.tc["llm/retry"] || 0));
  p("TASK: " + (r.firstUser.length > 500 ? r.firstUser.slice(0, 500) + " ..." : r.firstUser || "(none)"));
  p("LAST: " + (r.lastAsst.length > 700 ? r.lastAsst.slice(0, 700) + " ..." : r.lastAsst || "(none)"));
  p("");
}
fs.writeFileSync(out, outLines.join("\n"), "utf8");
console.log("WRITTEN " + out + " entries=" + rows.length);"
}

