function textOf(data) {
  if (!data) return "";
  let c = data.content;
  if (typeof c === "string") return c;
  if (Array.isArray(c)) return c.map(b => (typeof b === "string" ? b : (b && b.text) || "")).filter(Boolean).join("\\n");
  if (c && typeof c === "object") return (c.text || c.content || "");
  return "";
}
const clip = (s, n) => { s = (s || "").replace(/\\s+/g, " ").trim(); return s.length > n ? s.slice(0, n) + ` + "`" + `…(截)` + "`" + ` : s; };
// 1) 真人用户消息（过滤注入物）
p("## 1. USER MESSAGES (raw human turns)");
let um = 0;
