  let o; try { o = JSON.parse(lines[i]); } catch (e) { continue; }
  if (o.type !== "user/message") continue;
  const t = textOf(o.data || o);
  const head = t.slice(0, 40);
  // 跳过系统注入
  if (/^<goal_round>|^<system-reminder>|^MNEMON RUNTIME|^<runtime-memory|AgentTeams message|task update|\\[genui-action\\]/.test(t.trim())) continue;
  um++;
  p("L" + (i + 1) + " @" + (o.time ? new Date(o.time + 28800000).toISOString().replace("T", " ").slice(5, 16) : "?") + " :: " + clip(t, 700));
}
p("(total human-ish: " + um + ")");
p("");
// 2) todo/write 全序列（含最终状态）
p("## 2. TODO/WRITE SEQUENCE");
for (let i = 0; i < lines.length; i++) {
  let o; try { o = JSON.parse(lines[i]); } catch (e) { continue; }
  if (o.type !== "todo/write") continue;
  const d = o.data || {};
  const todos = d.todos || (d.content && d.content.todos) || [];
  const items = todos.map(t => "[" + t.status + "] " + t.content);
  p("L" + (i + 1) + " @" + (o.time ? new Date(o.time + 28800000).toISOString().replace("T", " ").slice(5, 16) : "?") + " ::");
  for (const it of items) p("   " + clip(it, 160));
}
p("");
// 3) goal/change
p("## 3. GOAL/CHANGE");
for (let i = 0; i < lines.length; i++) {
  let o; try { o = JSON.parse(lines[i]); } catch (e) { continue; }
  if (o.type !== "goal/change") continue;
  p("L" + (i + 1) + " :: " + clip(JSON.stringify(o.data || o), 800));
}
p("");
// 4) 最后 12 条 assistant/message
p("## 4. LAST 12 ASSISTANT MESSAGES");
const asst = [];
for (let i = 0; i < lines.length; i++) {
  let o; try { o = JSON.parse(lines[i]); } catch (e) { continue; }
  if (o.type === "assistant/message") asst.push({ i, o });
}
for (const { i, o } of asst.slice(-12)) {
  p("L" + (i + 1) + " @" + (o.time ? new Date(o.time + 28800000).toISOString().replace("T", " ").slice(5, 16) : "?") + " :: " + clip(textOf(o.data || o), 1500));
}
p("");
// 5) agent/inbox/spliced 首行采样（判断是否有团队在跑）
p("## 5. AGENT INBOX SAMPLE (first 30)");
let c = 0;
for (let i = 0; i < lines.length; i++) {
  let o; try { o = JSON.parse(lines[i]); } catch (e) { continue; }
  if (o.type !== "agent/inbox/spliced") continue;
  c++;
  if (c <= 30) p("L" + (i + 1) + " :: " + clip(textOf(o.data || o), 220));
}
p("(total: " + c + ")");
fs.writeFileSync(out, L.join("\\n"), "utf8");
console.log("WRITTEN " + out + " lines=" + L.length + " users=" + um + " asst=" + asst.length);"}

